{"content":"import math
_sumprod = getattr(math, "sumprod", None)
_dist = getattr(math, "dist", None)
_sqrt = math.sqrt

def mean_stdev(xs):
    n = len(xs)
    if n == 0:
        raise ValueError("empty")
    s = sum(xs)
    m = s / n
    if _sumprod is not None:
        try:
            s2 = _sumprod(xs, xs)
        except Exception:
            s2 = None
        if s2 is not None:
            try:
                var = s2 / n - m * m
            except Exception:
                var = float("nan")
            if var > 0 and var != float("inf"):
                mm = m * m
                if m == 0 or mm == 0 or mm == float("inf") or var >= 1e-9 * mm:
                    return (m, _sqrt(var))
    if _dist is not None:
        try:
            d = _dist(xs, [m] * n)
            return (m, d / _sqrt(n))
        except Exception:
            pass
    var2 = sum((x - m) * (x - m) for x in xs) / n
    return (m, _sqrt(var2))
