_sq = _m.sqrt
_fs = _m.fsum

def mean_stdev(xs):
    n = len(xs)
    if n == 0:
        raise ValueError("empty")
    s = sum(xs)
    m = s / n
    v = _sp(xs, xs) / n - m * m
    if v > 0.0:
        mm = m * m
        if mm == 0.0 or v >= mm * 1e-9:
            return (m, _sq(v))
    elif v == 0.0:
        return (m, 0.0)
    # Accurate fallback for cancellation / rounding edge cases
    # two-pass with high-accuracy summation
    try:
        vv = _fs((x - m) * (x - m) for x in xs) / n
    except Exception:
        vv = sum((x - m) * (x - m) for x in xs) / n
    if vv <= 0.0:
        return (m, 0.0)
    return (m, _sq(vv))
